import{_ as e,o,c as l,a3 as t}from"./chunks/framework.DMtjdCb-.js";const u=JSON.parse('{"title":"10. 困ったときは","description":"","frontmatter":{},"headers":[],"relativePath":"ja/troubleshooting.md","filePath":"ja/troubleshooting.md"}'),i={name:"ja/troubleshooting.md"};function r(n,a,h,d,s,c){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="_10-困ったときは" tabindex="-1">10. 困ったときは <a class="header-anchor" href="#_10-困ったときは" aria-label="Permalink to &quot;10. 困ったときは&quot;">​</a></h1><p>現在の症状から順に確認します。一項目ごとに元の操作を試すと、どの変更が有効だったか分かります。</p><h2 id="open-page" tabindex="-1">ページが開かない <a class="header-anchor" href="#open-page" aria-label="Permalink to &quot;ページが開かない {#open-page}&quot;">​</a></h2><ol><li>PC では起動ウィンドウ、Docker ではコンテナーが実行中か確認します。</li><li>起動ログに表示されたアドレスとポートを使用します。</li><li>スマートフォンでは <code>localhost</code> を実行機器の LAN アドレスに置き換えます。</li><li>ポートが使用中の場合は<a href="./docker.html">導入手順</a>で別のポートを選び、再起動します。</li></ol><h2 id="パスワードが分からない" tabindex="-1">パスワードが分からない <a class="header-anchor" href="#パスワードが分からない" aria-label="Permalink to &quot;パスワードが分からない&quot;">​</a></h2><p>初回の起動ウィンドウやコンテナーログで確認します。PC 版は <code>data/state/auth/initial-admin.txt</code>、標準 Docker 構成もプロジェクト内の同じ場所に初期アカウントを保存します。変更済みの場合はそのアカウントを使用し、別の管理者に管理を依頼できます。</p><h2 id="作品や画像がまだ出てこない" tabindex="-1">作品や画像がまだ出てこない <a class="header-anchor" href="#作品や画像がまだ出てこない" aria-label="Permalink to &quot;作品や画像がまだ出てこない&quot;">​</a></h2><p>初回は最近の作品を先に準備し、全作品と残りの画像を補完します。ホームの進捗と <strong>設定 → 診断</strong> を確認します。接続復旧後は再試行されます。過去の作品は全体の資料が揃ってから再検索できます。</p><h2 id="download" tabindex="-1">リソースがあるのに取得されない <a class="header-anchor" href="#download" aria-label="Permalink to &quot;リソースがあるのに取得されない {#download}&quot;">​</a></h2><ol><li>版の選択後、購読や計画の確認まで完了したか確認します。</li><li><strong>設定 → 接続</strong> で Ani-RSS・qBittorrent を確認します。</li><li>ダウンローダーでタスクの有無、保存先、接続可能なシーダーを確認します。</li><li>Torrent の結果が閉じている場合は展開し、グループと版を選択します。</li></ol><h2 id="保存済みの動画を再生できない" tabindex="-1">保存済みの動画を再生できない <a class="header-anchor" href="#保存済みの動画を再生できない" aria-label="Permalink to &quot;保存済みの動画を再生できない&quot;">​</a></h2><ol><li><strong>設定 → 接続</strong> でメディアフォルダーを読み取れるか確認します。</li><li>Docker は NAS のフォルダーをマウントしてから、コンテナーのパスを入力します。</li><li>走査完了を待ち、動画がある再生元を選びます。</li><li>本編判定や作品・話数の名前を確認し、<a href="./collections.html">既存のコレクション</a>も参照します。</li></ol><h2 id="プレーヤーが開かない・アドレスエラーになる" tabindex="-1">プレーヤーが開かない・アドレスエラーになる <a class="header-anchor" href="#プレーヤーが開かない・アドレスエラーになる" aria-label="Permalink to &quot;プレーヤーが開かない・アドレスエラーになる&quot;">​</a></h2><ol><li>操作中の機器へプレーヤーを導入し、ブラウザーの外部アプリ起動を許可します。</li><li>リストのアドレスをプレーヤーへコピーするか、リストをダウンロードします。</li><li>プレーヤーから届く AnimeMachine のアドレスを使用します。別機器の <code>localhost</code> はその機器自身です。</li><li>期限切れや新着話がある場合は、リストを作り直します。</li></ol><p>Windows の PotPlayer 拡張は正確な位置を記録します。VLC などはアクセスした話数を基にするため、誤判定は<a href="./continue-watching.html#correct">視聴記録</a>で修正できます。</p><h2 id="まとめ再生が空になる" tabindex="-1">まとめ再生が空になる <a class="header-anchor" href="#まとめ再生が空になる" aria-label="Permalink to &quot;まとめ再生が空になる&quot;">​</a></h2><p>対象シーズンに、購読中で最新話が未完了、かつ動画を再生できる TV 作品があるか確認します。一時停止・未購読・非表示・最新話完了の作品は新しいリストに含めません。</p><h2 id="ログのどこを確認するか" tabindex="-1">ログのどこを確認するか <a class="header-anchor" href="#ログのどこを確認するか" aria-label="Permalink to &quot;ログのどこを確認するか&quot;">​</a></h2><p><strong>設定 → ログ</strong> で警告・エラーに絞り、操作した時刻付近を確認します。解決しない場合はバージョン、導入方法、再現手順、関連するエラーを記録します。共有する画像・ログからはパスワード、キー、個人のパスを取り除きます。</p>',19)])])}const m=e(i,[["render",r]]);export{u as __pageData,m as default};
